const $=s=>document.querySelector(s), money=n=>"GH₵ "+Number(n||0).toLocaleString("en-GH",{minimumFractionDigits:2,maximumFractionDigits:2});
let page="dashboard",products=[],cart=[],category="All",searchTerm="";
const icons=["▧","◈","▣","◉","◇","▤","◍","▦"];
const esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const escapeData=d=>typeof d==="string"?esc(d):Array.isArray(d)?d.map(escapeData):d&&typeof d==="object"?Object.fromEntries(Object.entries(d).map(([k,v])=>[k,escapeData(v)])):d;
// Every text value returned by the server is HTML-escaped once here, so templates below can safely use innerHTML.
let api=async(url,opts={})=>{const r=await fetch("/api"+url,{headers:{"Content-Type":"application/json"},...opts});let d;try{d=await r.json()}catch{throw Error("Unexpected server response. Please try again.")}if(!r.ok)throw Error(d.error||"Something went wrong");return url.startsWith("/auth/")?d:escapeData(d)};
function toast(s){const t=$("#toast");t.textContent=s;t.classList.add("show");setTimeout(()=>t.classList.remove("show"),2600)}
function heading(title,desc,action=""){return `<div class="page-heading"><div><div class="eyebrow">SHOP MANAGEMENT</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function setPage(p){page=p;document.querySelectorAll(".nav-item").forEach(x=>x.classList.toggle("active",x.dataset.page===p));$("#crumb").textContent=({pos:"Point of Sale",products:"Products & Stock",sales:"Sales",purchases:"Purchases",customers:"Customers",suppliers:"Suppliers",expenses:"Expenses",inventory:"Inventory Control",reports:"Reports",finance:"Financial Statements",credit:"Credit & Balances",settings:"Settings"})[p]||"Dashboard";$("#sidebar").classList.remove("open");render()}
async function render(){try{if(page==="dashboard")await dashboard();else if(page==="pos")await pos();else if(page==="products")await productPage();else if(page==="sales")await salesPage();else if(page==="inventory")await inventoryControlPage();else if(page==="expenses")await expensesPage();else if(page==="customers")await customersPage();else if(page==="reports")await reportsPage();else if(page==="finance")await financePage();else if(page==="credit")await creditPage();else if(page==="settings")await settingsPage();else if(page==="purchases")await purchaseOrdersPage();else if(page==="suppliers")simplePage(page)}catch(e){toast(e.message)}}
async function dashboard(){const d=await api("/summary");const max=Math.max(1,...d.chart.map(x=>x.total));$("#content").innerHTML=heading("Good morning, Admin 👋","Here’s what’s happening with your shop today.",`<button class="btn" onclick="setPage('pos')">＋ New sale</button>`)+
`<div class="stats-grid">
${stat("Today's sales",money(d.today.total),"↗",`From ${d.today.orders} transactions`)}
${stat("Net revenue",money(d.all.revenue),"₵",`${d.all.orders} sales, after refunds`)}
${stat("Products in stock",d.inventory.units.toLocaleString(),"▤",`${d.inventory.products} product lines`)}
${stat("Low stock alerts",d.low,"⚑",d.low?"Items need restocking":"Stock levels look good")}
</div><div class="dashboard-grid"><div class="panel"><div class="panel-head"><div><h3>Sales overview</h3><p>Revenue activity · last 7 days</p></div><span class="subtle-link">Last 7 days</span></div><div class="chart">${Array.from({length:7},(_,i)=>{let x=d.chart[i],v=x?x.total:0;return `<div class="bar-group"><div class="bar ${i===6?'hot':''}" style="height:${Math.max(3,v/max*78)}%"></div><div class="bar-label">${x?x.day.split(" ")[0]:["M","T","W","T","F","S","S"][i]}</div></div>`}).join("")}</div></div><div class="panel"><div class="panel-head"><div><h3>Recent transactions</h3><p>Your latest completed sales</p></div><a class="subtle-link" href="#" onclick="setPage('sales');return false">View all ↗</a></div><div class="activity-list">${d.recent.length?d.recent.map(x=>`<div class="activity"><div class="activity-mark">↗</div><div class="activity-info"><b>${x.receipt_no}</b><small>${new Date(x.created_at+"Z").toLocaleString()}</small></div><div class="activity-amount">${money(x.total)}</div></div>`).join(""):`<div class="empty">No sales yet. Start your first sale in POS.</div>`}</div></div></div>
<div class="panel"><div class="panel-head"><div><h3>Inventory snapshot</h3><p>Current stock position</p></div><a class="subtle-link" href="#" onclick="setPage('products');return false">Manage products ↗</a></div><div class="table-wrap"><table><thead><tr><th>Inventory value</th><th>Units in stock</th><th>Product lines</th><th>Low stock items</th><th>Today's expenses</th></tr></thead><tbody><tr><td><strong>${money(d.inventory.stock_value)}</strong></td><td>${d.inventory.units}</td><td>${d.inventory.products}</td><td><span class="status ${d.low?'low':''}">${d.low} items</span></td><td>${money(d.expenses)}</td></tr></tbody></table></div></div>`}
function stat(label,value,ic,foot){return `<div class="stat-card"><div class="stat-top">${label}<span class="stat-icon">${ic}</span></div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></div>`}
async function loadProducts(){products=await api("/products")}
function posFiltered(){const q=searchTerm.trim().toLowerCase();return products.filter(p=>(category==="All"||p.category===category)&&(!q||`${p.name} ${p.sku} ${p.barcode||""}`.toLowerCase().includes(q)))}
function posGridHtml(){return posFiltered().map((p,i)=>`<button class="product-tile" onclick="addCart(${p.id})" ${p.stock<1?"disabled":""}><div class="product-emoji">${icons[i%icons.length]}</div><b>${p.name}</b><small>${p.sku} · ${p.stock} in stock</small><div class="product-price">${money(p.price)} <span class="stock-note">＋ Add</span></div></button>`).join("")||`<div class="empty">No matching products found.</div>`}
// Typing only redraws the product grid, so the search box keeps focus and every character (or a fast scanner burst) lands.
function posSearchInput(v){searchTerm=v;const g=$("#posGrid");if(g)g.innerHTML=posGridHtml()}
function posClearSearch(){searchTerm="";const el=$("#posSearch");if(el){el.value="";el.focus()}posSearchInput("")}
let audioCtx;
function beep(ok=true){try{audioCtx=audioCtx||new(window.AudioContext||window.webkitAudioContext)();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.frequency.value=ok?1100:220;g.gain.value=.06;o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+(ok?.08:.25))}catch{}}
// Scanners type the code and press Enter. An exact barcode/SKU match (case-insensitive) goes straight to the cart; a single search hit works too.
function scanCode(code){
 code=String(code||"").trim();if(!code)return false;
 const q=code.toLowerCase();
 let hit=products.find(p=>p.barcode&&String(p.barcode).toLowerCase()===q)||products.find(p=>String(p.sku||"").toLowerCase()===q);
 if(!hit){const list=posFiltered();if(list.length===1)hit=list[0]}
 if(!hit){beep(false);toast(`No product found for "${code}".`);return false}
 searchTerm="";
 if(addCart(hit.id)){beep(true);return true}
 beep(false);searchTerm=code;return false;
}
function posSearchKey(e){
 if(e.key!=="Enter")return;e.preventDefault();
 const el=e.target,code=el.value.trim();if(!code)return;
 if(!scanCode(code)){const s=$("#posSearch");if(s)s.select();else el.select()}
}
// ---- Camera scanner (phone or webcam): reads barcodes and QR codes with the browser's built-in BarcodeDetector. Needs HTTPS (or localhost) and camera permission. ----
let camStream=null,camTimer=null;
function stopCamera(){clearInterval(camTimer);camTimer=null;if(camStream){camStream.getTracks().forEach(t=>t.stop());camStream=null}}

// Fallback reader for browsers without BarcodeDetector (iPhone Safari, Firefox). Loaded on demand so other browsers never download it.
const ZXING_URL="https://cdn.jsdelivr.net/npm/@zxing/library@0.21.3/umd/index.min.js";
function loadScript(src){return new Promise((ok,fail)=>{const t=document.createElement("script");t.src=src;t.onload=ok;t.onerror=()=>fail(new Error("load failed"));document.head.appendChild(t)})}
async function zxingDetector(){
 if(!window.ZXing)await loadScript(ZXING_URL);
 const Z=window.ZXing;if(!Z)throw new Error("ZXing missing");
 const hints=new Map();hints.set(Z.DecodeHintType.TRY_HARDER,true);const BF=Z.BarcodeFormat;hints.set(Z.DecodeHintType.POSSIBLE_FORMATS,[BF.QR_CODE,BF.EAN_13,BF.EAN_8,BF.UPC_A,BF.UPC_E,BF.CODE_128,BF.CODE_39,BF.CODE_93,BF.ITF,BF.CODABAR,BF.DATA_MATRIX,BF.PDF_417,BF.AZTEC]);
 const reader=new Z.MultiFormatReader();reader.setHints(hints);
 const canvas=document.createElement("canvas"),ctx=canvas.getContext("2d",{willReadFrequently:true});
 return{async detect(video){
  const w=video.videoWidth,h=video.videoHeight;if(!w||!h)return[];
  canvas.width=w;canvas.height=h;ctx.drawImage(video,0,0,w,h);
  try{const bmp=new Z.BinaryBitmap(new Z.HybridBinarizer(new Z.HTMLCanvasElementLuminanceSource(canvas)));return[{rawValue:reader.decode(bmp).getText()}]}
  catch{return[]} // nothing readable in this frame
 }};
}
// The built-in BarcodeDetector often exists but doesn't work (Windows/Linux Chrome, some Android builds), so we test it and fall back to ZXing.
async function nativeDetector(){
 if(!("BarcodeDetector" in window))return null;
 try{
  const want=["qr_code","ean_13","ean_8","upc_a","upc_e","code_128","code_39","code_93","itf","codabar","data_matrix","pdf417","aztec"];
  const have=BarcodeDetector.getSupportedFormats?await BarcodeDetector.getSupportedFormats():want;
  const formats=want.filter(f=>have.includes(f));
  if(!formats.length)return null;
  const d=new BarcodeDetector({formats});
  const c=document.createElement("canvas");c.width=c.height=32;
  await d.detect(c); // throws if the platform has no barcode service
  return d;
 }catch{return null}
}
// Starts the camera in a <video> element and calls onCode(code) for every read. Returns true when scanning started.
async function startCamScan(v,statusEl,onCode){
 const say=t=>{if(statusEl)statusEl.textContent=t};
 if(!navigator.mediaDevices?.getUserMedia){toast("This browser can't use the camera. Use a handheld scanner instead.");return false}
 if(!window.isSecureContext){toast("Camera scanning needs a secure (https) connection.");return false}
 stopCamera();
 say("Starting camera…");
 let det=await nativeDetector(),usingZx=false;
 const loadZx=async()=>{say("Loading the scanner…");det=await zxingDetector();usingZx=true};
 if(!det){try{await loadZx()}catch{toast("Couldn't load the camera scanner. Check your internet connection, or use a handheld scanner.");return false}}
 const tries=[{video:{facingMode:{ideal:"environment"},width:{ideal:1920},height:{ideal:1080}},audio:false},{video:{facingMode:{ideal:"environment"}},audio:false},{video:true,audio:false}];
 let err;
 for(const c of tries){try{camStream=await navigator.mediaDevices.getUserMedia(c);err=null;break}catch(e){err=e;if(e&&(e.name==="NotAllowedError"||e.name==="SecurityError"))break}}
 if(err||!camStream){const n=err&&err.name;toast(n==="NotAllowedError"?"Camera access was blocked. Allow the camera for this site and try again.":n==="NotFoundError"?"No camera was found on this device.":n==="NotReadableError"?"The camera is being used by another app. Close it and try again.":"Couldn't start the camera.");return false}
 v.muted=true;v.setAttribute("muted","");v.srcObject=camStream;
 try{await v.play()}catch{}
 try{const t=camStream.getVideoTracks()[0],caps=t.getCapabilities?.()||{};if(caps.focusMode?.includes("continuous"))await t.applyConstraints({advanced:[{focusMode:"continuous"}]})}catch{}
 say("Scanning…");
 let last="",lastAt=0,busy=false,fails=0;
 clearInterval(camTimer);
 camTimer=setInterval(async()=>{
  if(busy||v.readyState<2||!camStream)return;busy=true;
  try{
   const r=await det.detect(v);fails=0;
   if(r.length){const c=r[0].rawValue,now=Date.now();
    // Ignore the same code seen again within 2 seconds so one scan = one read.
    if(c&&(c!==last||now-lastAt>2000)){last=c;lastAt=now;onCode(c,say)}}
  }catch{
   if(!usingZx&&++fails>=3){try{await loadZx();fails=0;say("Scanning…")}catch{say("Scanner unavailable. Check your internet connection.")}}
  }
  busy=false;
 },250);
 return true;
}
// POS: scan items straight into the order.
async function openCameraScanner(){
 modal("Scan with camera","Point the camera at a barcode or QR code. Each read adds the item to the order.",`<video id="camVideo" playsinline webkit-playsinline muted autoplay style="width:100%;max-height:50vh;border-radius:12px;background:#000"></video><p class="muted" id="camStatus">Starting camera…</p>`,"Done",closeModal);
 const cancel=$("#modal .btn.light");if(cancel)cancel.onclick=closeModal;
 const ok=await startCamScan($("#camVideo"),$("#camStatus"),(c,say)=>{say(scanCode(c)?`Added: ${c}`:`Not added: ${c}`)});
 if(!ok)closeModal();
}
// Add/Edit product: fill the Barcode field from the camera without leaving the form.
async function scanIntoBarcode(){
 const box=$("#fBarcodeCam"),input=$("#fBarcode");if(!box||!input)return;
 if(box.style.display==="block"){stopCamera();box.style.display="none";return}
 box.style.display="block";
 const ok=await startCamScan($("#fBarcodeVideo"),$("#fBarcodeStatus"),(c)=>{input.value=c;beep(true);stopCamera();box.style.display="none";toast(`Barcode captured: ${c}`);input.focus()});
 if(!ok)box.style.display="none";
}
// If the cashier clicked elsewhere, the first scanned character moves focus back to the search box.
document.addEventListener("keydown",e=>{
 if(page!=="pos"||e.ctrlKey||e.metaKey||e.altKey||e.key.length!==1)return;
 if($("#modalBackdrop")?.classList.contains("show")||$("#authScreen")?.classList.contains("show"))return;
 const t=e.target;if(t&&(/^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName)||t.isContentEditable))return;
 const s=$("#posSearch");if(s)s.focus();
});
async function pos(reload=true){
 if(reload||!products.length)await loadProducts();
 const a=document.activeElement,had=a&&a.id==="posSearch",sel=had?[a.selectionStart,a.selectionEnd]:null;
 const cats=["All",...new Set(products.map(p=>p.category))];
 $("#content").innerHTML=heading("Point of Sale","Fast checkout, accurate stock and simple payments.",`<span class="status">● Register open</span>`)+
`<div class="pos-layout"><div><div class="toolbar"><input id="posSearch" class="search" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="⌕  Search products or scan barcode..." value="${esc(searchTerm)}" oninput="posSearchInput(this.value)" onkeydown="posSearchKey(event)"><button class="btn outline" onclick="posClearSearch()">Clear</button><button class="btn outline" onclick="openCameraScanner()">📷 Scan with camera</button></div><div class="pos-categories">${cats.map(c=>`<button class="chip ${c===category?'active':''}" data-cat="${esc(c)}" onclick="category=this.dataset.cat;pos(false)">${c}</button>`).join("")}</div><div class="product-grid" id="posGrid">${posGridHtml()}</div></div><div class="panel cart-panel"><div class="cart-head"><h3>Current order</h3><button class="subtle-link" onclick="cart=[];pos(false)">Clear all</button></div><div class="cart-body">${cart.length?cart.map(x=>`<div class="cart-row"><div class="cart-product"><b>${x.name}</b><small>${money(x.price)} each</small></div><div class="qty"><button onclick="changeQty(${x.id},-1)">−</button><b>${x.quantity}</b><button onclick="changeQty(${x.id},1)">+</button></div><b class="line-total">${money(x.price*x.quantity)}</b></div>`).join(""):`<div class="empty">Your basket is empty.<br>Choose products to get started.</div>`}</div><div class="cart-total"><div class="total-line"><span>Subtotal</span><b>${money(cart.reduce((s,x)=>s+x.price*x.quantity,0))}</b></div><div class="total-line"><span>Discount</span><b id="discountLabel">${money(0)}</b></div><div class="total-line grand"><span>Total due</span><span>${money(cart.reduce((s,x)=>s+x.price*x.quantity,0))}</span></div><button class="btn" onclick="checkout()" ${cart.length?"":"disabled"}>Proceed to payment →</button></div></div></div>`
 // Keep the cursor in the search box after every redraw; on a desktop with a mouse, also focus it when POS opens so scans work immediately.
 if(had||(reload&&matchMedia("(pointer:fine)").matches)){const el=$("#posSearch");if(el){el.focus();if(sel&&sel[0]!=null)try{el.setSelectionRange(sel[0],sel[1])}catch{}}}
}
function addCart(id){const p=products.find(x=>x.id===id);if(!p||p.stock<1){toast("This product is out of stock.");return false}let x=cart.find(x=>x.id===id);if(x){if(x.quantity>=p.stock){toast("Not enough stock available.");return false}x.quantity++}else cart.push({id:p.id,name:p.name,price:p.price,quantity:1});pos(false);return true}
function changeQty(id,delta){let x=cart.find(x=>x.id===id),p=products.find(p=>p.id===id);if(!x)return;x.quantity+=delta;if(x.quantity<1)cart=cart.filter(a=>a.id!==id);else if(x.quantity>p.stock){x.quantity=p.stock;toast("Available stock limit reached.")}pos(false)}
function modal(title,desc,body,submitText,fn){$("#modal").innerHTML=`<h2>${title}</h2><p>${desc}</p>${body}<div class="modal-actions"><button class="btn light" onclick="closeModal()">Cancel</button><button class="btn" id="modalSubmit">${submitText}</button></div>`;$("#modalBackdrop").classList.add("show");$("#modalSubmit").onclick=fn}
function closeModal(){if(typeof stopCamera==="function")stopCamera();$("#modalBackdrop").classList.remove("show")}
async function checkout(){
 const subtotal=cart.reduce((s,x)=>s+x.price*x.quantity,0),customers=await api("/customers");
 modal("Complete payment","Record full payment, part payment or customer credit.",`<div class="panel inset"><div class="total-line"><span>Order total</span><b>${money(subtotal)}</b></div></div>
 <div class="field"><label>Customer (required for credit)</label><select id="payCustomer"><option value="">Walk-in customer</option>${customers.map(c=>`<option value="${c.id}">${c.name} ${c.phone||""} · Store credit: ${money(c.store_credit_balance||0)}</option>`).join("")}</select></div>
 <div class="field"><label>Discount (GH₵)</label><input id="payDiscount" type="number" min="0" value="0"></div><div class="field"><label>Tax (GH₵)</label><input id="payTax" type="number" min="0" value="0"></div>
 <div class="field"><label>Payment status</label><select id="payMethod"><option>Cash</option><option>Mobile Money</option><option>Card</option><option>Bank Transfer</option><option>Store Credit</option><option>Part payment</option><option>Credit</option></select></div>
 <div class="field" id="payTenderWrap" hidden><label>Tender method for amount received</label><select id="payTender"><option>Cash</option><option>Mobile Money</option><option>Card</option><option>Bank Transfer</option><option>Store Credit</option></select></div>
 <div class="field"><label>Amount received (GH₵)</label><input id="payAmount" type="number" min="0" step=".01" value="${subtotal.toFixed(2)}"></div><div class="field"><label>Cashier</label><input id="payCashier" value="${esc(currentUser?.name||"Shop Admin")}" readonly></div>`,
 "Confirm sale",async()=>{try{
 const d=await api("/sales",{method:"POST",body:JSON.stringify({items:cart.map(x=>({product_id:x.id,quantity:x.quantity})),discount:+$("#payDiscount").value,tax:+$("#payTax").value,payment_method:$("#payMethod").value,tender_method:$("#payTender").value,amount_paid:+$("#payAmount").value,cashier:$("#payCashier").value,customer_id:$("#payCustomer").value?+$("#payCustomer").value:null})});
 const soldItems=cart.map(x=>({...x}));cart=[];closeModal();toast(d.balance_due>0?`Sale saved. Customer balance: ${money(d.balance_due)}`:"Sale completed successfully.");printReceipt(d,soldItems);setPage("pos")
 }catch(e){toast(e.message)}});
 const method=$("#payMethod"),amount=$("#payAmount");
 const recalc=()=>{const d=Math.min(Math.max(0,+$("#payDiscount").value||0),subtotal),t=Math.max(0,+$("#payTax").value||0);if(!["Credit","Part payment"].includes(method.value))amount.value=(subtotal-d+t).toFixed(2)};
 $("#payDiscount").oninput=recalc;$("#payTax").oninput=recalc;
 const tenderWrap=$("#payTenderWrap");method.onchange=()=>{tenderWrap.hidden=method.value!=="Part payment";if(method.value==="Credit")amount.value="0";else if(method.value!=="Part payment")recalc()};
}
// ---- Receipts: thermal-friendly layout printed through a hidden frame (no pop-up to block) ----
let shopSettings={business_name:"My Shop",business_address:"",business_phone:"",receipt_footer:"Thank you for shopping with us!"};
async function loadSettings(){try{shopSettings=await api("/settings")}catch{}}
const PAPER_KEY="shopflow_paper_mm";
function getPaperMm(){try{return localStorage.getItem(PAPER_KEY)==="58"?58:80}catch{return 80}}
function setPaperMm(v){try{localStorage.setItem(PAPER_KEY,String(+v===58?58:80))}catch{}}
// Values from the API arrive HTML-escaped already, so they are safe to place in this markup as-is.
function receiptHtml(s,items,mm){
 const w58=mm===58,printable=w58?"48mm":"72mm",fs=w58?11:12;
 const when=s.created_at?new Date(String(s.created_at).replace(" ","T")+"Z"):new Date();
 const row=(a,b,cls="")=>`<div class="r ${cls}"><span>${a}</span><span>${b}</span></div>`;
 const lines=items.map(x=>{const name=x.name??x.product_name,qty=+x.quantity,unit=+(x.unit_price??x.price),total=x.line_total!==undefined?+x.line_total:unit*qty;return `<div class="it"><div>${name}</div>${row(`${qty} × ${money(unit)}`,money(total))}</div>`}).join("");
 const n=v=>Number(v||0);
 const extra=(n(s.discount)>0||n(s.tax)>0)?row("Subtotal",money(n(s.total)+n(s.discount)-n(s.tax)))+(n(s.discount)>0?row("Discount","−"+money(s.discount)):"")+(n(s.tax)>0?row("Tax",money(s.tax)):""):"";
 return `<!doctype html><html><head><meta charset="utf-8"><title>${s.receipt_no}</title><style>
@page{margin:0}
*{box-sizing:border-box}html,body{margin:0;padding:0;background:#fff}
body{width:${printable};margin:0 auto;padding:3mm 0 8mm;font:${fs}px/1.35 "Courier New",monospace;color:#000}
.c{text-align:center}.shop{font-size:${fs+3}px;font-weight:700;word-break:break-word}.sm{font-size:${fs-1}px}
.r{display:flex;justify-content:space-between;gap:6px}.r span:last-child{white-space:nowrap;text-align:right}
.it{margin:3px 0}.it>div:first-child{word-break:break-word}.b{font-weight:700}.tot{font-size:${fs+2}px}
hr{border:0;border-top:1px dashed #000;margin:5px 0}p{margin:2px 0}
</style></head><body>
<div class="c"><div class="shop">${shopSettings.business_name}</div>${shopSettings.business_address?`<div class="sm">${shopSettings.business_address}</div>`:""}${shopSettings.business_phone?`<div class="sm">Tel: ${shopSettings.business_phone}</div>`:""}<p>SALES RECEIPT</p></div><hr>
<p>Receipt: ${s.receipt_no}<br>Date: ${when.toLocaleString()}<br>Cashier: ${s.cashier||""}</p><hr>
${lines}<hr>${extra}
${row("Total",money(s.total),"b tot")}${row(s.payment_method?`Paid (${s.payment_method})`:"Paid",money(s.amount_paid))}${n(s.change_due)>0?row("Change",money(s.change_due)):""}${n(s.balance_due)>0?row("Balance due",money(s.balance_due),"b"):""}
${shopSettings.receipt_footer?`<hr><p class="c">${shopSettings.receipt_footer}</p>`:""}</body></html>`}
function printReceipt(s,items=[]){
 const mm=getPaperMm(),html=receiptHtml(s,items,mm);
 document.getElementById("receiptFrame")?.remove();
 const f=document.createElement("iframe");f.id="receiptFrame";f.setAttribute("aria-hidden","true");f.setAttribute("title","Receipt");
 f.style.cssText=`position:fixed;right:0;bottom:0;width:${Math.ceil(mm/25.4*96)}px;height:1px;border:0;opacity:0;pointer-events:none`;
 // "@page size: 80mm auto" is not valid in Chrome, so measure the rendered receipt and give the page an exact width x height (one page, no blank paper).
 f.onload=()=>{try{const d=f.contentDocument,h=Math.ceil(d.documentElement.scrollHeight*25.4/96)+2,st=d.createElement("style");st.textContent=`@page{size:${mm}mm ${h}mm;margin:0}`;d.head.appendChild(st);f.contentWindow.focus();f.contentWindow.print()}catch{toast("Could not open the print dialog.")}};
 f.srcdoc=html;document.body.appendChild(f);
}
async function productPage(){await loadProducts();$("#content").innerHTML=heading("Products & Stock","Manage your catalogue, pricing and stock levels.",`<button class="btn" onclick="productModal()">＋ Add product</button>`)+`<div class="panel"><div class="toolbar"><input class="search" placeholder="Search product, SKU, barcode or category..." oninput="filterTable(this.value,'productsTable')"><span class="spacer"></span><span class="subtle-link">${products.length} product records</span></div><div class="table-wrap"><table id="productsTable"><thead><tr><th>Product</th><th>SKU</th><th>Barcode</th><th>Category</th><th>Selling price</th><th>Cost price</th><th>Stock</th><th>Status</th><th>Action</th></tr></thead><tbody>${products.map(p=>`<tr><td><strong>${p.name}</strong></td><td>${p.sku}</td><td>${p.barcode||"—"}</td><td>${p.category}</td><td>${money(p.price)}</td><td>${money(p.cost)}</td><td>${p.stock}</td><td><span class="status ${p.stock===0?'out':p.stock<=p.reorder_level?'low':''}">${p.stock===0?'Out of stock':p.stock<=p.reorder_level?'Low stock':'In stock'}</span></td><td><button class="btn light" onclick="productModal(${p.id})">Edit</button></td></tr>`).join("")}</tbody></table></div></div>`}
function productModal(id){const p=products.find(x=>x.id===id)||{sku:"",barcode:"",name:"",category:"General",price:0,cost:0,stock:0,reorder_level:5};modal(id?"Edit product":"Add a product","Keep product details and stock quantities up to date.",`<div class="form-grid"><div class="field"><label>Product name *</label><input id="fName" value="${p.name}"></div><div class="field"><label>SKU (your internal code)</label><input id="fSku" value="${p.sku}"></div><div class="field"><label>Barcode (type, use a handheld scanner, or use the camera)</label><div style="display:flex;gap:8px"><input id="fBarcode" autocomplete="off" autocapitalize="off" spellcheck="false" style="flex:1" onkeydown="if(event.key==='Enter'){event.preventDefault()}" value="${esc(p.barcode||"")}"><button type="button" class="btn outline" onclick="scanIntoBarcode()">📷 Scan</button></div><div id="fBarcodeCam" style="display:none;margin-top:8px"><video id="fBarcodeVideo" playsinline webkit-playsinline muted autoplay style="width:100%;max-height:40vh;border-radius:12px;background:#000"></video><p class="muted" id="fBarcodeStatus">Starting camera…</p></div></div><div class="field"><label>Category</label><input id="fCategory" value="${p.category}"></div><div class="field"><label>Selling price (GH₵) *</label><input id="fPrice" type="number" min="0" step=".01" value="${p.price}"></div><div class="field"><label>Cost price (GH₵)</label><input id="fCost" type="number" min="0" step=".01" value="${p.cost}" ${id?'readonly title="Cost comes from purchases"':''}></div><div class="field"><label>Stock quantity</label><input id="fStock" type="number" min="0" value="${p.stock}" ${id?'readonly title="Change stock via Inventory Control"':''}></div><div class="field"><label>Reorder level</label><input id="fReorder" type="number" min="0" value="${p.reorder_level}"></div></div>`,"Save product",async()=>{const body={name:$("#fName").value,sku:$("#fSku").value,barcode:$("#fBarcode").value,category:$("#fCategory").value,price:+$("#fPrice").value,cost:+$("#fCost").value,stock:+$("#fStock").value,reorder_level:+$("#fReorder").value};try{await api(id?`/products/${id}`:"/products",{method:id?"PUT":"POST",body:JSON.stringify(body)});closeModal();toast("Product saved.");productPage()}catch(e){toast(e.message)}})}
function filterTable(v,id){document.querySelectorAll(`#${id} tbody tr`).forEach(r=>r.style.display=r.innerText.toLowerCase().includes(v.toLowerCase())?"":"none")}
async function salesPage(){const sales=await api("/sales");$("#content").innerHTML=heading("Sales history","Review completed transactions and payment records.")+`<div class="panel"><div class="toolbar"><input class="search" placeholder="Search receipt or payment..." oninput="filterTable(this.value,'salesTable')"><span class="spacer"></span><button class="btn outline" onclick="setPage('pos')">＋ New sale</button></div><div class="table-wrap"><table id="salesTable"><thead><tr><th>Receipt</th><th>Date & time</th><th>Cashier</th><th>Payment</th><th>Amount</th><th>Action</th></tr></thead><tbody>${sales.map(s=>`<tr><td><strong>${s.receipt_no}</strong></td><td>${new Date(s.created_at+"Z").toLocaleString()}</td><td>${s.cashier}</td><td>${s.payment_method}</td><td><strong>${money(s.total)}</strong></td><td><button class="btn light" onclick="viewSale(${s.id})">Details</button></td></tr>`).join("")||`<tr><td colspan="6" class="empty">No transactions recorded yet.</td></tr>`}</tbody></table></div></div>`}
async function viewSale(id){const [s,items]=await Promise.all([api("/sales"),api(`/sales/${id}/items`)]);const sale=s.find(x=>x.id===id);modal(sale.receipt_no,"Transaction details",`<div class="receipt">${items.map(x=>`<div class="receipt-line"><span>${x.product_name} × ${x.quantity}</span><b>${money(x.line_total)}</b></div>`).join("")}<hr><div class="receipt-line"><b>Total</b><b>${money(sale.total)}</b></div><div class="receipt-line"><span>Paid</span><span>${money(sale.amount_paid)}</span></div><div class="receipt-line"><span>Change</span><span>${money(sale.change_due)}</span></div></div>`,"Print receipt",()=>printReceipt(sale,items))}
async function expensesPage(){const xs=await api("/expenses");$("#content").innerHTML=heading("Expenses","Track operating costs and other shop expenses.",`<button class="btn" onclick="expenseModal()">＋ Record expense</button>`)+`<div class="panel"><div class="table-wrap"><table><thead><tr><th>Description</th><th>Category</th><th>Date</th><th>Amount</th></tr></thead><tbody>${xs.map(x=>`<tr><td><strong>${x.title}</strong></td><td>${x.category}</td><td>${new Date(x.created_at+"Z").toLocaleDateString()}</td><td>${money(x.amount)}</td></tr>`).join("")||`<tr><td colspan="4" class="empty">No expenses recorded.</td></tr>`}</tbody></table></div></div>`}
function expenseModal(){modal("Record an expense","Capture a shop expense for reporting.",`<div class="field"><label>Description *</label><input id="exTitle" placeholder="e.g. Electricity bill"></div><div class="field"><label>Category</label><select id="exCat"><option>Utilities</option><option>Rent</option><option>Transport</option><option>Salaries</option><option>Supplies</option><option>General</option></select></div><div class="field"><label>Amount (GH₵) *</label><input id="exAmount" type="number" min="0" step=".01"></div><div class="field"><label>Note</label><input id="exNote"></div>`,"Save expense",async()=>{try{await api("/expenses",{method:"POST",body:JSON.stringify({title:$("#exTitle").value,category:$("#exCat").value,amount:+$("#exAmount").value,note:$("#exNote").value})});closeModal();toast("Expense recorded.");expensesPage()}catch(e){toast(e.message)}})}
async function customersPage(){const xs=await api("/customers");$("#content").innerHTML=heading("Customers","Build customer relationships and keep contact details.",`<button class="btn" onclick="customerModal()">＋ Add customer</button>`)+`<div class="panel"><div class="table-wrap"><table><thead><tr><th>Customer</th><th>Phone</th><th>Email</th><th>Added</th></tr></thead><tbody>${xs.map(x=>`<tr><td><strong>${x.name}</strong></td><td>${x.phone||"—"}</td><td>${x.email||"—"}</td><td>${new Date(x.created_at+"Z").toLocaleDateString()}</td></tr>`).join("")||`<tr><td colspan="4" class="empty">No customers added yet.</td></tr>`}</tbody></table></div></div>`}
function customerModal(){modal("Add customer","Add a customer profile to your shop.",`<div class="field"><label>Customer name *</label><input id="cuName"></div><div class="field"><label>Phone</label><input id="cuPhone"></div><div class="field"><label>Email</label><input id="cuEmail" type="email"></div>`,"Save customer",async()=>{try{await api("/customers",{method:"POST",body:JSON.stringify({name:$("#cuName").value,phone:$("#cuPhone").value,email:$("#cuEmail").value})});closeModal();toast("Customer saved.");customersPage()}catch(e){toast(e.message)}})}
async function reportsPage(){const d=await api("/reports/overview");$("#content").innerHTML=heading("Business reports","Monitor sales performance and product movement.",`<a class="btn outline" href="/api/export">↓ Export all data</a>`)+`<div class="stats-grid">${stat("Gross profit (est.)",money(d.gross),"↗","Based on recorded product costs")}${stat("Sales days recorded",d.daily.length,"▦","Daily sales summaries")}${stat("Top products",d.top.length,"▤","Products with recorded sales")}${stat("Export","JSON","↓","Download your shop records")}</div><div class="report-grid"><div class="panel"><div class="panel-head"><h3>Best-selling products</h3></div><table><thead><tr><th>Product</th><th>Qty sold</th><th>Revenue</th></tr></thead><tbody>${d.top.map(x=>`<tr><td><strong>${x.name}</strong></td><td>${x.quantity}</td><td>${money(x.revenue)}</td></tr>`).join("")||`<tr><td colspan="3" class="empty">No sales data yet.</td></tr>`}</tbody></table></div><div class="panel"><div class="panel-head"><h3>Daily sales</h3></div><table><thead><tr><th>Date</th><th>Orders</th><th>Revenue</th></tr></thead><tbody>${d.daily.map(x=>`<tr><td>${x.date}</td><td>${x.orders}</td><td>${money(x.sales)}</td></tr>`).join("")||`<tr><td colspan="3" class="empty">No sales data yet.</td></tr>`}</tbody></table></div></div>`}
